	'pr_d6' => 'Pro Panel und Jahr: Ersatzteile, Remote-Updates, telefonischer Support',
	'pr_i1' => 'Zaseki Panel',
	'pr_i2' => 'Schreibtisch-Tags, Packung mit 20 Stück',
	'pr_i3' => 'Gebäudeinstallation',
	'pr_i4' => 'Zusätzliches Etagenpanel',
	'pr_i5' => 'Grundriss-Aktualisierung',
	'pr_i6' => 'Servicepaket',
